#include <cstdio>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    if (n <= 0 || m < 0 || m > 9 * n || (m == 0 && n > 1)) {
        printf("-1 -1");
        return 0;
    }

    vector<int> smallest(n, 0), largest(n, 0);

    int sum = m;
    for (int i = 0; i < n; ++i) {
        largest[i] = min(9, sum);
        sum -= largest[i];
    }

    if (m > 0) {
        smallest[0] = 1;
        sum = m - 1;

        for (int i = n - 1; i >= 0; --i) {
            int add = min(9 - smallest[i], sum);
            smallest[i] += add;
            sum -= add;
        }
    }

    for (int digit : smallest)
        printf("%d", digit);

    printf(" ");

    for (int digit : largest)
        printf("%d", digit);

    return 0;
}

